recursive_split(text, chunk_size, separators):

    if len(text) <= chunk_size:
        return [text.strip()]

    if not separators:
        return [text[i:i+chunk_size] for i in range(0, len(text), chunk_size)]

    sep = separators[0]

    # fallback to hard split
    if sep == "":
        return [text[i:i+chunk_size] for i in range(0, len(text), chunk_size)]

    parts = text.split(sep)

    chunks = []
    current = parts[0]

    for part in parts[1:]:

        candidate = current + sep + part

        if len(candidate) <= chunk_size:
            current = candidate
        else:
            chunks.append(current.strip())
            current = part

    if current:
        chunks.append(current.strip())

    # recursively refine oversized chunks
    result = []
    for chunk in chunks:
        if len(chunk) > chunk_size:
            result.extend(
                recursive_split(chunk, chunk_size, separators[1:])
            )
        else:
            result.append(chunk)

add_overlap(chunks, overlap):

    if overlap <= 0:
        return chunks

    overlapped = []

    for i, chunk in enumerate(chunks):

        if i == 0:
            overlapped.append(chunk)
        else:
            overlap_text = chunks[i-1][-overlap:]
            overlapped.append(overlap_text + chunk)

    return overlapped

